import fs from 'node:fs';import{gzipSync}from'node:zlib';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('groove_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
function setup(sim,kind){}
function params(kind){return kind==='amount'?{action:'set-amount',grooveAmount:.4}:kind==='max-amount'?{action:'set-amount',grooveAmount:1.3125}:kind==='name'?{action:'edit',grooveRef:'groove:groove-1',name:'Renamed'}:{action:'edit',grooveRef:'groove:groove-1',name:'Custom',base:4,quantizationAmount:.4,randomAmount:.2,timingAmount:kind==='percentage'?75:.8,velocityAmount:kind==='negative'?-25:.3};}
function alter(sim,kind){if(kind.includes('amount'))sim.state.groovePool.amount=.9;else sim.state.groovePool.grooves[0].name='Manual';}
const rows=[];for(const kind of ['amount','edit'])for(const action of ['preview','apply']){const valid=action==='preview'?params(kind):{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of (action==='preview'?['action','grooveAmount','grooveRef','name','base','quantizationAmount','randomAmount','timingAmount','velocityAmount']:Object.keys(valid))){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-101,-100,-1,0,0.5,1,1.3,1.3125,1.3126,16,17,100,101,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const sim=new DeterministicLiveSimulator();setup(sim,'session-midi');const host=new McpHost(sim);let result;try{result=clean(await host[action==='preview'?'liveGroovePreviewAsync':'liveGrooveApplyAsync'](1,args));}catch(e){result={error:e.message};}rows.push({action,args,result});}}
const workflows=[];for(const kind of ['amount','max-amount','edit','name','percentage','negative'])for(const scenario of ['normal','expire','epoch','identity-edit','source-content','null-prior','missing-prior','missing-identity','missing-groove-identity','target-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','apply-clamped','apply-float32','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-content','undo-epoch','undo-unrequested']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();setup(sim,kind);let fault='',fired=false,afterInvoke=false;if(scenario==='missing-identity')delete sim.state.set.objectIdentity;if(scenario==='null-prior'){sim.state.groovePool.amount=null;sim.state.groovePool.grooves[0].randomAmount=null;}if(scenario==='missing-prior'){delete sim.state.groovePool.amount;delete sim.state.groovePool.grooves[0].randomAmount;}if(scenario==='missing-groove-identity')delete sim.state.groovePool.grooves[0].objectIdentity;
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));if(i.operation==='groove.read'){readFault();return sim.invoke(i);}const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&['apply-invalid-identity','apply-invalid-fingerprint'].includes(fault)){fired=true;result[fault.endsWith('identity')?'objectIdentity':'createdFingerprint']='';}if(!fired&&fault==='apply-clamped'){fired=true;alter(sim,kind);}if(!fired&&fault==='apply-float32'){fired=true;if(kind.includes('amount'))sim.state.groovePool.amount=Math.fround(sim.state.groovePool.amount);else for(const f of ['quantizationAmount','randomAmount','timingAmount','velocityAmount'])sim.state.groovePool.grooves[0][f]=Math.fround(sim.state.groovePool.grooves[0][f]);}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const args=params(kind);const preview=await host.liveGroovePreviewAsync(1,args);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveGrooveApplyAsync(results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')sim.state.set.objectIdentity='other';if(scenario==='source-content')sim.state.groovePool.grooves[0].name='Manual';if(scenario==='target-identity')sim.state.groovePool.grooves[0].objectIdentity='other';if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-identity'){if(kind.includes('amount'))sim.state.set.objectIdentity='other';else sim.state.groovePool.grooves[0].objectIdentity='other';}if(scenario==='undo-unrequested')sim.state.groovePool.grooves[0].randomAmount=.8;if(scenario==='undo-other-content'){alter(sim,kind);}if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-epoch','undo-unrequested'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}
const readErrors=[];for(const read of [null,{},[],{revision:'x'},{revision:'x',grooves:{}},{revision:'x',grooves:[null]},{revision:'x',grooves:[false,1,'x',[]]},{revision:'x',grooves:[{ref:'groove:groove-1',objectIdentity:'groove'}]}]){const sim=new DeterministicLiveSimulator();sim.invokeAsync=async()=>structuredClone(read);const host=new McpHost(sim);const result=clean(await host.liveGroovePreviewAsync(1,params('name')));readErrors.push({read,result});}
fs.writeFileSync(new URL('host-groove-oracle.json.gz',import.meta.url),gzipSync(JSON.stringify({rows,workflows,readErrors}),{level:9}));console.log({rows:rows.length,workflows:workflows.length});
